import java.util.*;

public class Main {
    void hourglassPattern(int n) {
        int totalRows = 2 * n - 1;
        for (int r = 1; r <= totalRows; r++) {         // r counts every row, top edge to bottom edge
            int m = Math.min(r, 2 * n - r);              // this row's distance from the nearest tip
            int gap = m - 1;
            int stars = 2 * (n - m) + 1;
            for (int j = 0; j < gap + stars; j++) {       // check every column this row actually uses
                if (j < gap) {
                    System.out.print(" ");                    // still inside the leading gap
                } else {
                    System.out.print("*");                    // inside the star region
                }
            }
            System.out.println();                          // move to the next line after the row
        }
    }

    public static void main(String[] args) {
        Main solution = new Main();
        solution.hourglassPattern(4);
    }
}

