import java.util.*;

public class Main {
    void hourglassPattern(int n) {
        int totalRows = 2 * n - 1;
        StringBuilder sb = new StringBuilder();
        for (int r = 1; r <= totalRows; r++) {
            int m = Math.min(r, 2 * n - r);
            sb.append(" ".repeat(m - 1)).append("*".repeat(2 * (n - m) + 1));  // build every row directly
            if (r < totalRows) {
                sb.append('\n');
            }
        }
        System.out.println(sb);                          // output the whole pattern with a single call
    }

    public static void main(String[] args) {
        Main solution = new Main();
        solution.hourglassPattern(4);
    }
}

